import json
import os
import sys


def main():
    dir_path = sys.argv[1]

    files_read = sorted(
        name for name in os.listdir(dir_path)
        if name.endswith('.json') and os.path.isfile(os.path.join(dir_path, name))
    )

    costs = []
    for name in files_read:
        file_path = os.path.join(dir_path, name)
        try:
            with open(file_path, 'r') as f:
                data = json.load(f)
        except (json.JSONDecodeError, OSError):
            continue

        if isinstance(data, dict) and 'cost_usd' in data:
            costs.append(data['cost_usd'])

    total = sum(costs) if costs else 0
    mean = total / len(costs) if costs else None

    summary = {
        'total': total,
        'mean': mean,
        'files_read': files_read,
    }

    with open('summary.json', 'w') as f:
        json.dump(summary, f, indent=2)


if __name__ == '__main__':
    main()
